34	/// 寡头集合。伙伴分配器的顶层，不再合并。
35	pub trait OligarchyCollection: BuddyLine {
36	    /// 提取任何 `count` 个满足 `align_order` 的内存块。
37	    ///
38	    /// 返回提取到第一个元素的序号。若找不到连续的那么多块，返回 [`None`]。
39	    fn take_any(&mut self, align_order: usize, count: usize) -> Option<usize>;
