45	/// 伙伴集合。一组同阶的伙伴。
46	pub trait BuddyCollection: BuddyLine {
47	    /// 提取任何一个满足 `align_order` 的内存块。
48	    ///
49	    /// 返回提取到的元素。若集合为空则无法提取，返回 [`None`]。
50	    fn take_any(&mut self, align_order: usize) -> Option<usize>;
